window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[61]={"id":"061","numero":61,"titre":"Sémiologie et classifications des troubles mentaux de l’enfant à la personne âgée","objectifs":[{"id":"61-1","rang":"A","rubrique":"Définition","titre":"Connaître les signes, symptômes et syndromes en psychiatrie","contenu":"<div class=\"notion-course\"><p>La sémiologie psychiatrique distingue trois niveaux. Un <strong><span>signe</span></strong> est un élément <em>objectif</em>, observé par le clinicien (mimique figée, ralentissement moteur). Un <strong><span>symptôme</span></strong> est <em>subjectif</em>, rapporté par le patient (tristesse, angoisse, idées intrusives). Un <strong><span>syndrome</span></strong> est un <span>regroupement organisé et cohérent de signes et de symptômes</span> — il oriente le diagnostic mais ne suffit pas, à lui seul, à poser un trouble.</p>\n      <p>L'examen psychiatrique est <strong>clinique</strong> : il explore <strong><span>8 domaines sémiologiques</span></strong> de l'expérience vécue et des conduites du patient, ainsi que leur <span>évolution dans le temps</span>.</p>\n\n      <p><strong><span>Les</span> <span <span=\"\">&gt;10</span> grands syndromes psychiatriques</strong></p>\n      <table>\n        <thead><tr><th>Syndrome</th><th>Caractérisation</th></tr></thead>\n        <tbody>\n          <tr><td><span>Positif</span></td><td>Expérience psychique en « <strong>plus</strong> » : <span>idées délirantes</span>, <span>hallucinations</span></td></tr>\n          <tr><td><span>Négatif</span></td><td>Expérience psychique « <strong>diminuée</strong> » ou en « moins » (retrait, émoussement affectif)</td></tr>\n          <tr><td><span>Désorganisation</span></td><td>Expérience psychique « <strong>désorganisée</strong> » (pensée, discours, comportement)</td></tr>\n          <tr><td><span>Thymique</span></td><td>Diminution (<span>dépressif</span>) ou augmentation (<span>maniaque</span>) de l'humeur</td></tr>\n          <tr><td><span>Anxieux</span></td><td>Réaction d'<strong>alerte</strong> de l'organisme</td></tr>\n          <tr><td><span>Dépendance</span></td><td>Difficulté à contrôler un comportement source de plaisir</td></tr>\n          <tr><td><span>Suicidaire</span></td><td><span>Mort considérée comme la seule issue</span> de l'épuisement psychique</td></tr>\n          <tr><td><span>Catatonique</span></td><td><span><span class=\"nc-red nc-bold\">Perturbation grave de l'organisation psychomotrice</span></span></td></tr>\n          <tr><td><span>Agitation</span></td><td>Augmentation de l'activité motrice</td></tr>\n          <tr><td><span>Chez l'enfant</span></td><td>Plus spécifiquement : syndrome d'<span><span class=\"nc-red\">hyperactivité</span></span>, d'<span>inattention</span>, <span>autistique</span></td></tr>\n        </tbody>\n      </table>\n\n      <p><strong><span>Les</span> 8 domaines sémiologiques de l'examen psychiatrique</strong></p>\n      <table>\n        <thead><tr><th>Domaine</th><th>Ce qu'on explore</th></tr></thead>\n        <tbody>\n          <tr><td><span>Présentation / Contact</span></td><td><span>Apparence</span> (soignée, négligée, incurie) ; <span>mimique</span> (hyper/hypomimie, amimie) ; <span><span class=\"nc-gray_bg nc-bold\">activités psychomotrices</span></span> (agitation, ralentissement, <span class=\"nc-red nc-bold\">raptus</span>)</td></tr>\n          <tr><td><span>Discours et pensée</span></td><td><span>Langage</span> (dynamique, forme) et <span>pensée</span> (dynamique, contenu) — <span class=\"nc-blue nc-bold\">recherche</span> d'un trouble du <em>cours</em> ou du <em>contenu</em> (délire, obsessions)</td></tr>\n          <tr><td><span>Perception</span></td><td><span><span class=\"nc-gray_bg nc-bold\">Hallucinations</span></span><span class=\"nc-gray_bg nc-bold\">, </span><span><span class=\"nc-gray_bg nc-bold\">illusions</span></span>, <span class=\"nc-gray_bg nc-bold\">modification du seuil de sensibilité</span>, <span>déréalisation</span>, <span>dépersonnalisation</span></td></tr>\n          <tr><td><span><span class=\"nc-red\">Attention</span> / Mémoire</span></td><td><span class=\"nc-red\">Attention</span> (<span class=\"nc-blue_bg\">hypoprosexie</span>, distractibilité, hypervigilance) ; <span class=\"nc-gray_bg nc-bold\">mémoire </span><span><span class=\"nc-gray_bg nc-bold\">épisodique</span></span> et de <span>travail</span> (reviviscences, flashbacks)</td></tr>\n          <tr><td><span>Affectivité</span></td><td><span>Émotions</span> (réponses affectives <span class=\"nc-red nc-bold\">immédiates</span> à un stimulus) et <span>humeur</span> (tonalité affective globale et <span class=\"nc-red nc-bold\">durable</span>)</td></tr>\n          <tr><td><span>Jugement et insight</span></td><td>Qualité du <span>jugement</span> et <span>conscience du trouble</span> (insight) — oriente la dangerosité et l'indication d'<span>hospitalisation</span></td></tr>\n          <tr><td><span>Fonctions physiologiques</span></td><td><span>Sommeil</span>, <span>alimentation</span>, <span>sexualité</span>, signes sympathiques d'anxiété, hyperréactivité neurovégétative</td></tr>\n          <tr><td><span>Comportement</span></td><td>Conduites <span>suicidaires</span> ; comportements de <span>réduction</span> de l'anxiété (<span>évitement</span>, <span>compulsion</span>) ; fonctionnement interpersonnel</td></tr>\n        </tbody>\n      </table>\n\n      <p><strong>Hallucinations — deux familles à distinguer</strong></p>\n      <table>\n        <thead><tr><th>Famille</th><th>Caractère</th><th>Exemples</th><th>Orientation diagnostique</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span>Intrapsychiques</span></td>\n            <td>Phénomène vécu <em>dans</em> la pensée, <span>sans sensorialité ni spatialité</span>, perçu comme étranger au sujet (« <span><span class=\"nc-red nc-bold\">perte de l'intimité psychique</span></span> »)</td>\n            <td>Écho, <span class=\"nc-blue nc-bold\">vol</span>, <span class=\"nc-blue nc-bold\">divulgation</span>, <span class=\"nc-blue nc-bold\">devinement</span> de la pensée, pensée imposée</td>\n            <td>Phénomènes d’influence/automatisme mental possibles dans un trouble psychotique, sans diagnostic automatique.</td>\n          </tr>\n          <tr>\n            <td><span><span class=\"nc-red nc-bold\">Sensorielles</span></span></td>\n            <td>Avec <span>sensorialité, spatialité et conviction de réalité</span></td>\n            <td>Auditives (acoustico-verbales), <span class=\"nc-yellow_bg\">visuelles</span>, <span class=\"nc-yellow_bg\">tactiles</span>, <span class=\"nc-yellow_bg\">olfactives</span>, <span class=\"nc-yellow_bg\">gustatives</span>, cénesthésiques</td>\n            <td>Origines psychiatriques, neurologiques, toxiques ou médicamenteuses selon le contexte ; le caractère isolé ne suffit pas à parler d’hallucinose.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 63 — Trouble schizophrénique · 64 — <span>Trouble bipolaire</span> · 66 — Trouble dépressif · 351 — Agitation et délire aigu · 352 — Crise d'angoisse et attaque de panique · 353 — Risque et conduite suicidaire</em></p><h4>Discriminations sémiologiques à savoir expliquer</h4><table><thead><tr><th>Terme</th><th>Repère clinique</th></tr></thead><tbody><tr><td>Hallucination / illusion</td><td>Hallucination : <span class=\"nc-yellow_bg\">perception sans objet</span> extérieur correspondant. Illusion : déformation d’une perception réelle. Préciser modalité, conviction, critique, fréquence et contexte.</td></tr><tr><td>Hallucinose</td><td>Expérience hallucinatoire avec critique de son caractère pathologique généralement conservée ; ne se définit pas par le fait d’être isolée.</td></tr><tr><td>Délire / obsession</td><td>Délire : conviction fausse, non partagée culturellement, peu accessible à la critique. Obsession : pensée/image/impulsion intrusive, répétitive et habituellement vécue comme indésirable ; insight variable.</td></tr><tr><td>Dépersonnalisation / déréalisation</td><td>Étrangeté de soi / du monde environnant ; le sujet peut conserver la conscience du caractère subjectif de l’expérience.</td></tr><tr><td>Tachypsychie / <span class=\"nc-blue_bg\">logorrhée</span></td><td>Accélération du cours de la pensée / abondance du discours. Bradypsychie : ralentissement de la pensée.</td></tr><tr><td><span class=\"nc-red nc-bold\">Barrage</span> / <span class=\"nc-orange nc-bold\">fading</span></td><td>Interruption brusque du discours / extinction progressive du débit et de la voix ; à interpréter dans le contexte.</td></tr><tr><td><span class=\"nc-red nc-bold\">Anhédonie</span> / <span class=\"nc-blue_bg\">aboulie</span> / apragmatisme</td><td>Diminution du plaisir / difficulté à vouloir et initier / difficulté à réaliser une action finalisée.</td></tr><tr><td><span class=\"nc-blue_bg\">Akathisie</span> / agitation</td><td>Impatience motrice avec besoin de bouger, parfois iatrogène / activité motrice excessive, à caractériser plutôt qu’à attribuer d’emblée à l’anxiété.</td></tr><tr><td><span class=\"nc-red_bg\">Catatonie</span></td><td>Ensemble de signes psychomoteurs (<span class=\"nc-blue_bg\">stupeur</span>, mutisme, négativisme, postures, échophénomènes…) possible dans plusieurs maladies ; rechercher cause somatique et complications.</td></tr></tbody></table><h4>Décrire un délire sans conclure trop vite</h4><ul><li>Thème, mécanisme (hallucinatoire, interprétatif, intuitif…), organisation, adhésion, vécu affectif et retentissement.</li><li>Chronologie, niveau de conscience et d’<span class=\"nc-red\">attention</span>, médicaments/substances, contexte culturel et causes somatiques.</li><li>Risque suicidaire/hétéroagressif, capacité à se protéger et à consentir : le manque d’insight seul ne suffit pas à décider une hospitalisation sans consentement.</li></ul><div class=\"callout\"><p>En entretien : décrire d’abord, regrouper en syndrome ensuite, puis discuter diagnostic et urgence. Une hallucination n’est pas synonyme de schizophrénie ; une confusion aiguë est une urgence médicale.</p></div></div><details><summary>Sources et compléments</summary><p>Relecture du 13 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181988919cb587e47b711?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Classifications des troubles mentaux (61)</a></li><li><a href=\"https://www.cunea.fr/sites/default/files/ref_psy_add_4ed.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e édition (2024)</a></li><li><a href=\"https://livret.uness.fr/lisa/2026/Conna%C3%AEtre_les_bases_des_classifications_des_troubles_mentaux_de_l%27enfant_%C3%A0_la_personne_%C3%A2g%C3%A9e\" target=\"_blank\" rel=\"noopener noreferrer\">LiSA 2026 · Item 61</a></li><li><a href=\"https://www.psychiatry.org/psychiatrists/practice/dsm\" target=\"_blank\" rel=\"noopener noreferrer\">APA · DSM-5-TR et mises à jour</a></li></ul><p></p></details><details><summary>Situations de départ LiSA vérifiées</summary><ul><li><a href=\"https://livret.uness.fr/lisa/2026/Anxi%C3%A9t%C3%A9_SDD-116\" target=\"_blank\" rel=\"noopener noreferrer\">SDD 116 · Anxiété</a><ul><li>Caractériser l’anxiété, sa chronologie et son retentissement ; chercher dépression, suicide et addictions.</li><li>Discuter suivi, traitements et recours au psychiatre ; prévenir le mésusage des benzodiazépines.</li></ul></li></ul><p>Attendus consultés directement sur LiSA 2026 le 13 octobre 2026. Les arbres ATLAS sont des synthèses pédagogiques reliées aux cours complets.</p></details>","frequence":4},{"id":"61-2","rang":"B","rubrique":"Définition","titre":"Connaître l’approche catégorielle en psychiatrie","contenu":"<div class=\"notion-course\"><h4>Approche catégorielle</h4><p>Une catégorie diagnostique regroupe des patients partageant un ensemble de critères. L’approche catégorielle demande si les critères du trouble sont remplis ; elle facilite communication, <span class=\"nc-blue nc-bold\">recherche</span> et décisions, sans résumer toute la personne.</p><ol><li>Identifier la grande famille à partir de la sémiologie : psychotique, thymique, anxieuse, neurodéveloppementale…</li><li>Préciser le trouble et vérifier durée, retentissement et exclusions.</li><li>Spécifier sévérité, évolution et caractéristiques pertinentes ; ne pas réutiliser comme sous-type DSM-5 actuel l’ancienne « schizophrénie paranoïde ».</li><li>Chercher les comorbidités psychiatriques, addictives et somatiques.</li></ol><h4>Complément dimensionnel</h4><p>Décrire aussi les dimensions et leur intensité : humeur, anxiété, cognition, symptômes psychotiques, fonctionnement. Un seuil catégoriel ne rend pas compte à lui seul de la sévérité ou des besoins de soins. Les systèmes actuels utilisent également des dimensions et spécificateurs.</p><div class=\"callout\"><p>Le diagnostic principal est lié au motif et au contexte de prise en charge ; il ne dispense jamais de rechercher les troubles associés ni les ressources de la personne.</p></div></div><details><summary>Sources et compléments</summary><p>Relecture du 13 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181988919cb587e47b711?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Classifications des troubles mentaux (61)</a></li><li><a href=\"https://www.cunea.fr/sites/default/files/ref_psy_add_4ed.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e édition (2024)</a></li><li><a href=\"https://livret.uness.fr/lisa/2026/Conna%C3%AEtre_les_bases_des_classifications_des_troubles_mentaux_de_l%27enfant_%C3%A0_la_personne_%C3%A2g%C3%A9e\" target=\"_blank\" rel=\"noopener noreferrer\">LiSA 2026 · Item 61</a></li><li><a href=\"https://www.psychiatry.org/psychiatrists/practice/dsm\" target=\"_blank\" rel=\"noopener noreferrer\">APA · DSM-5-TR et mises à jour</a></li><li><a href=\"https://www.who.int/publications/i/item/9789240077263\" target=\"_blank\" rel=\"noopener noreferrer\">OMS · CIM-11 et descriptions diagnostiques (2024)</a></li></ul><p></p></details>","frequence":0},{"id":"61-3","rang":"A","rubrique":"Définition","titre":"Connaître les critères pour définir un trouble mental","contenu":"<div class=\"notion-course\"><h4>Quatre axes du raisonnement diagnostique</h4><table><thead><tr><th>Axe</th><th>Question à poser</th></tr></thead><tbody><tr><td>Sémiologie</td><td>Quels signes et symptômes positifs, regroupés en syndrome, sont effectivement présents ?</td></tr><tr><td>Temps</td><td>Quel début, quelle durée, quelle évolution ? Rupture récente ou difficultés développementales/durables ?</td></tr><tr><td>Retentissement</td><td>Quelle <span class=\"nc-red nc-bold\">détresse</span>, altération de la qualité de vie, de l’autonomie ou du fonctionnement social/scolaire/professionnel ?</td></tr><tr><td>Différentiels</td><td>Un autre trouble, une substance, un médicament ou une affection somatique explique-t-il mieux le tableau ?</td></tr></tbody></table><p>Ces axes sont à examiner conjointement, puis les critères propres au trouble sont appliqués. Une rupture avec l’état antérieur est un exemple de trajectoire, pas une obligation universelle : les TND ou certains troubles de la personnalité peuvent être anciens.</p><h4>Place des examens complémentaires</h4><ul><li>Diagnostic principalement clinique ; pas de biomarqueur de routine confirmant à lui seul la plupart des troubles psychiatriques.</li><li>Examens orientés par la clinique pour rechercher une cause somatique/toxique ou une comorbidité.</li><li>Ils servent aussi à établir un bilan préthérapeutique et à surveiller les effets indésirables : leur rôle ne se limite donc pas aux diagnostics différentiels.</li></ul><div class=\"callout\"><p>Un syndrome dépressif peut survenir dans une dépression unipolaire, un trouble bipolaire, une affection somatique ou une situation liée à une substance. Nommer le syndrome est le début du raisonnement, pas sa conclusion.</p></div></div><details><summary>Sources et compléments</summary><p>Relecture du 13 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181988919cb587e47b711?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Classifications des troubles mentaux (61)</a></li><li><a href=\"https://www.cunea.fr/sites/default/files/ref_psy_add_4ed.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e édition (2024)</a></li><li><a href=\"https://livret.uness.fr/lisa/2026/Conna%C3%AEtre_les_bases_des_classifications_des_troubles_mentaux_de_l%27enfant_%C3%A0_la_personne_%C3%A2g%C3%A9e\" target=\"_blank\" rel=\"noopener noreferrer\">LiSA 2026 · Item 61</a></li><li><a href=\"https://www.psychiatry.org/psychiatrists/practice/dsm\" target=\"_blank\" rel=\"noopener noreferrer\">APA · DSM-5-TR et mises à jour</a></li></ul><p></p></details>","frequence":0},{"id":"61-4","rang":"B","rubrique":"Définition","titre":"Connaître les systèmes nosographiques existants","contenu":"<div class=\"notion-course\"><h4>Classer les troubles, décrire le fonctionnement</h4><table><thead><tr><th>Système</th><th>Auteur / portée</th><th>Usage et limites</th></tr></thead><tbody><tr><td>CIM</td><td><span class=\"nc-red nc-bold\">OMS</span> ; ensemble des maladies et problèmes de santé</td><td>Classification et codage diagnostiques, statistiques de santé. La CIM-11 est la révision internationale actuelle ; son déploiement dépend des pays et systèmes. Ne pas la confondre avec une cotation d’actes.</td></tr><tr><td>DSM-5 / DSM-5-TR</td><td>American Psychiatric Association ; troubles mentaux</td><td>Critères descriptifs utilisés en clinique et <span class=\"nc-blue nc-bold\">recherche</span>. DSM-5-TR : révision du texte publiée en 2022 ; les critères doivent être lus dans la version concernée.</td></tr><tr><td>CIF</td><td><span class=\"nc-red nc-bold\">OMS</span> ; fonctionnement, handicap et santé</td><td>Fonctions/structures, activités, participation et facteurs contextuels ; complément à une classification de maladies.</td></tr></tbody></table><p>Nosologie : étude et organisation des catégories de maladies ; nosographie : description/classification. Les classifications psychiatriques sont surtout descriptives et ne prouvent pas une cause biologique unique. Elles évoluent avec les connaissances.</p><p>CIM et DSM ont de nombreux points communs mais ne sont pas identiques : durées, regroupements et spécificateurs peuvent différer. Indiquer le système utilisé. La connaissance de la CIM-11 n’implique pas que tous les systèmes hospitaliers aient abandonné la CIM-10.</p></div><details><summary>Sources et compléments</summary><p>Relecture du 13 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181988919cb587e47b711?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Classifications des troubles mentaux (61)</a></li><li><a href=\"https://www.cunea.fr/sites/default/files/ref_psy_add_4ed.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e édition (2024)</a></li><li><a href=\"https://livret.uness.fr/lisa/2026/Conna%C3%AEtre_les_bases_des_classifications_des_troubles_mentaux_de_l%27enfant_%C3%A0_la_personne_%C3%A2g%C3%A9e\" target=\"_blank\" rel=\"noopener noreferrer\">LiSA 2026 · Item 61</a></li><li><a href=\"https://www.psychiatry.org/psychiatrists/practice/dsm\" target=\"_blank\" rel=\"noopener noreferrer\">APA · DSM-5-TR et mises à jour</a></li><li><a href=\"https://www.who.int/publications/i/item/9789240077263\" target=\"_blank\" rel=\"noopener noreferrer\">OMS · CIM-11 et descriptions diagnostiques (2024)</a></li></ul><p></p></details>","frequence":0},{"id":"61-5","rang":"A","rubrique":"Définition","titre":"Connaître les grandes catégories diagnostiques chez l’enfant, l’adolescent et l’adulte","contenu":"<div class=\"notion-course\"><p>Plusieurs grandes familles structurent le raisonnement. Les huit familles ci-dessous sont des repères pédagogiques, et non une liste exhaustive des catégories du DSM ou de la CIM.</p>\n      <table>\n        <thead><tr><th>Catégorie</th><th>Caractérisation</th></tr></thead>\n        <tbody>\n          <tr><td><span><span class=\"nc-yellow_bg\">Troubles du neurodéveloppement</span></span></td><td>Débutent durant le développement psychomoteur : trouble du développement <span class=\"nc-red\">intellectuel</span>, troubles des <span><span class=\"nc-red\">acquisitions</span></span> et des <span><span class=\"nc-red\">apprentissages</span></span>, <span>TDAH</span>, <span>TSA</span>, <span class=\"nc-red\">tics</span></td></tr>\n          <tr><td><span><span class=\"nc-yellow_bg\">Troubles psychotiques</span></span></td><td><span><span class=\"nc-red\">Altération du contact à la réalité</span></span></td></tr>\n          <tr><td><span><span class=\"nc-yellow_bg\">Troubles de l'humeur</span></span></td><td>Perturbation des <span>affects</span> et de leur régulation, avec modifications cognitives et physiologiques associées</td></tr>\n          <tr><td><span><span class=\"nc-yellow_bg\">Troubles anxieux</span></span></td><td><span>Anxiété excessive</span> et perturbations comportementales apparentées ; se distinguent par l'objet ou la situation déclenchante</td></tr>\n          <tr><td><span><span class=\"nc-yellow_bg\">Trouble obsessionnel compulsif</span></span></td><td>Idées <span>obsessionnelles</span> et comportements de <span>compulsions</span></td></tr>\n          <tr><td><span><span class=\"nc-yellow_bg\">Troubles à symptomatologie somatique</span></span></td><td>Symptômes somatiques associés à préoccupations, émotions ou comportements excessifs et retentissants ; une maladie somatique peut coexister et l’absence d’explication organique n’est pas un critère obligatoire.</td></tr>\n          <tr><td><span>Troubles liés à un traumatisme ou au stress</span></td><td>Symptômes psychiques, cognitifs, comportementaux et neurovégétatifs après exposition à un <span>événement traumatique</span></td></tr>\n          <tr><td><span>Addictions</span></td><td>Perte de contrôle de l'usage d'un objet de gratification — <span>substance psychoactive</span> ou <span>comportement</span></td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Spécificités chez l'enfant.</strong> On retrouve plus spécifiquement le syndrome d'<span><span class=\"nc-red\">hyperactivité</span></span>, le syndrome d'<span>inattention</span> et le syndrome <span>autistique</span>.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 55 — Développement psychomoteur · 63 — Trouble schizophrénique · 64 — <span>Trouble bipolaire</span> · 65 — Trouble délirant persistant · 66 — Trouble dépressif · 67 — Troubles envahissants du développement · 68 — Troubles du comportement de l'ado · 71 — Troubles conduite alimentaire</em></p><h4>Compléter la carte des familles</h4><ul><li>Troubles des conduites alimentaires ; troubles de la personnalité ; troubles disruptifs, du contrôle des impulsions et des conduites.</li><li>Troubles neurocognitifs, troubles du sommeil, troubles dissociatifs et autres catégories selon le système.</li><li>Dépression et bipolarité : familles distinguées dans les classifications actuelles, même si le terme pédagogique « <span class=\"nc-yellow_bg\">troubles de l’humeur</span> » reste utilisé.</li></ul><p>Chez l’enfant, interpréter toute sémiologie en fonction de l’âge développemental et des milieux de vie. Les TND peuvent persister à l’âge adulte ; anxiété, dépression et autres troubles ne sont pas réservés aux adultes.</p></div><details><summary>Sources et compléments</summary><p>Relecture du 13 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181988919cb587e47b711?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Classifications des troubles mentaux (61)</a></li><li><a href=\"https://www.cunea.fr/sites/default/files/ref_psy_add_4ed.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e édition (2024)</a></li><li><a href=\"https://livret.uness.fr/lisa/2026/Conna%C3%AEtre_les_bases_des_classifications_des_troubles_mentaux_de_l%27enfant_%C3%A0_la_personne_%C3%A2g%C3%A9e\" target=\"_blank\" rel=\"noopener noreferrer\">LiSA 2026 · Item 61</a></li><li><a href=\"https://www.psychiatry.org/psychiatrists/practice/dsm\" target=\"_blank\" rel=\"noopener noreferrer\">APA · DSM-5-TR et mises à jour</a></li><li><a href=\"https://www.who.int/publications/i/item/9789240077263\" target=\"_blank\" rel=\"noopener noreferrer\">OMS · CIM-11 et descriptions diagnostiques (2024)</a></li></ul><p></p></details>","frequence":0}],"astuces":[{"type":"piege","titre":"Sémiologie d’abord","contenu":"<div class=\"notion-course\"><p>Décrire les phénomènes avant d’attribuer un diagnostic.</p></div>"},{"type":"piege","titre":"Hallucinose","contenu":"<div class=\"notion-course\"><p>Le caractère isolé d’une hallucination ne définit pas une hallucinose.</p></div>"},{"type":"piege","titre":"Temporalité","contenu":"<div class=\"notion-course\"><p>Une rupture récente n’est pas exigée pour tous les troubles.</p></div>"}],"strategie":{"Démarche diagnostique":"<div class=\"notion-course\"><ul><li>Explorer les huit domaines, leur chronologie et leur retentissement.</li><li>Syndrome, différentiels, catégorie, spécification puis comorbidités.</li></ul></div>","Prise en charge":"<div class=\"notion-course\"><ul><li>Évaluer urgence et risques, partager l’explication et organiser les soins selon les besoins.</li></ul></div>","Examens complémentaires":"<div class=\"notion-course\"><ul><li>Bilan orienté par clinique, comorbidités et traitement ; pas d’examen confirmatoire universel.</li></ul></div>"},"liensGlobaux":[{"href":"https://app.notion.com/p/2ad37f85d94181988919cb587e47b711?pvs=204","label":"Ton cours Notion ↗"},{"href":"https://www.cunea.fr/sites/default/files/ref_psy_add_4ed.pdf","label":"CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e édition (2024) ↗"},{"href":"https://livret.uness.fr/lisa/2026/Conna%C3%AEtre_les_bases_des_classifications_des_troubles_mentaux_de_l%27enfant_%C3%A0_la_personne_%C3%A2g%C3%A9e","label":"LiSA 2026 · Item 61 ↗"},{"href":"https://www.psychiatry.org/psychiatrists/practice/dsm","label":"APA · DSM-5-TR et mises à jour ↗"},{"href":"https://www.who.int/publications/i/item/9789240077263","label":"OMS · CIM-11 et descriptions diagnostiques (2024) ↗"},{"href":"https://livret.uness.fr/lisa/2026/Anxi%C3%A9t%C3%A9_SDD-116","label":"LiSA · SDD 116 — Anxiété ↗"}],"cards":[{"i":"602fdf99280b","n":61,"o":"61-1","u":"Définition","t":"Connaître les signes, symptômes et syndromes en psychiatrie","q":"Quelles sont les caractéristiques des hallucinations intrapsychiques et sensorielles, et ce qu'elles évoquent sur le plan diagnostique ?","a":"<div class=\"notion-course\"><ul><li>Intrapsychiques : phénomènes vécus dans la pensée comme étrangers au sujet (influence, écho…).</li><li><span class=\"nc-red nc-bold\">Sensorielles</span> : expériences perceptives, sans objet extérieur correspondant, dans différentes modalités.</li><li>Origines multiples ; une hallucination isolée n’est pas forcément une hallucinose. Celle-ci suppose notamment une critique conservée.</li></ul></div>"},{"i":"69121c69ddc2","n":61,"o":"61-1","u":"Définition","t":"Connaître les signes, symptômes et syndromes en psychiatrie","q":"Quels sont les 8 domaines sémiologiques explorés lors de l'examen psychiatrique ?","a":"<div class=\"notion-course\"><p>L'examen psychiatrique explore <strong>8 domaines</strong> principaux de l'expérience vécue et des conduites du patient :</p><ul><li>La <strong>présentation/contact</strong> (<span class=\"nc-gray_bg nc-bold\">apparence, mimique</span>, <span class=\"nc-gray_bg nc-bold\">activités psychomotrices</span>).</li><li>Le <strong>discours et la pensée</strong> (langage, dynamique et contenu de la pensée).</li><li>La <strong>perception</strong> (<span class=\"nc-gray_bg nc-bold\">hallucinations, illusions</span>, déréalisation, dépersonnalisation).</li><li>L'<strong><span class=\"nc-red\">attention</span>/mémoire</strong> (<span class=\"nc-blue_bg\">hypoprosexie</span>, distractibilité, reviviscences).</li><li>L'<strong>affectivité</strong> (émotions, humeur).</li><li>Le <strong>jugement et l'insight</strong> (conscience du trouble).</li><li>Les <strong>fonctions physiologiques</strong> (sommeil, alimentation, sexualité).</li><li>Le <strong>comportement</strong> (conduites suicidaires, comportements de réduction de l'anxiété).</li></ul></div>"},{"i":"c91572081f32","n":61,"o":"61-1","u":"Définition","t":"Connaître les signes, symptômes et syndromes en psychiatrie","q":"Comment les concepts de signe, symptôme et syndrome sont-ils définis en sémiologie psychiatrique ?","a":"<div class=\"notion-course\"><p>En sémiologie psychiatrique, la distinction est la suivante :</p><ul><li>Un <strong>signe</strong> est un élément <strong>objectif</strong>, observable par le clinicien (ex. : mimique figée, ralentissement moteur).</li><li>Un <strong>symptôme</strong> est <strong>subjectif</strong>, rapporté par le patient (ex. : tristesse, angoisse, idées intrusives).</li><li>Un <strong>syndrome</strong> est un regroupement cohérent de signes et de symptômes, orientant le diagnostic mais n'étant pas suffisant pour poser un trouble seul.</li></ul></div>"},{"i":"4f45fa4f672d","n":61,"o":"61-3","u":"Définition","t":"Connaître les critères pour définir un trouble mental","q":"Pourquoi un syndrome seul ne suffit pas à diagnostiquer un trouble mental selon l'objectif Rang A ?","a":"<div class=\"notion-course\"><ul><li>Il faut vérifier sémiologie, durée/évolution, retentissement et diagnostics différentiels selon les critères du trouble.</li><li>Un même syndrome peut avoir plusieurs causes.</li></ul></div>"},{"i":"52ad8a9269c6","n":61,"o":"61-3","u":"Définition","t":"Connaître les critères pour définir un trouble mental","q":"Quelle est l'utilité des examens complémentaires dans le diagnostic d'un trouble mental ?","a":"<div class=\"notion-course\"><ul><li>Rechercher causes somatiques/toxiques et comorbidités, établir le bilan préthérapeutique et surveiller les traitements.</li><li>Pas de biomarqueur de routine confirmant seul la plupart des troubles psychiatriques.</li></ul></div>"},{"i":"5a61847104b6","n":61,"o":"61-3","u":"Définition","t":"Connaître les critères pour définir un trouble mental","q":"Quels quatre axes structurent le diagnostic d’un trouble mental ?","a":"<div class=\"notion-course\"><ul><li>Sémiologie, évolution temporelle, retentissement et diagnostics différentiels.</li><li>Appliquer ensuite les critères spécifiques ; la rupture récente n’est pas obligatoire dans tous les troubles.</li></ul></div>"},{"i":"a6c8ca98af2d","n":61,"o":"61-3","u":"Définition","t":"Connaître les critères pour définir un trouble mental","q":"Quels sont les quatre critères indispensables pour définir un trouble mental ?","a":"<div class=\"notion-course\"><ul><li>Signes/symptômes ; début, durée et évolution ; <span class=\"nc-red nc-bold\">détresse</span> ou retentissement ; <span class=\"nc-blue nc-bold\">recherche</span> d’une meilleure explication.</li><li>Une trajectoire développementale ancienne ne nécessite pas de rupture récente.</li></ul></div>"},{"i":"01149cb855c8","n":61,"o":"61-5","u":"Définition","t":"Connaître les grandes catégories diagnostiques chez l’enfant, l’adolescent et l’adulte","q":"Comment définit-on un trouble psychotique ?","a":"<div class=\"notion-course\"><p>Un trouble psychotique est défini par une <strong><span class=\"nc-red\">altération du contact à la réalité</span></strong>.</p></div>"},{"i":"056aad777e57","n":61,"o":"61-5","u":"Définition","t":"Connaître les grandes catégories diagnostiques chez l’enfant, l’adolescent et l’adulte","q":"Quelles sont les spécificités des troubles mentaux retrouvés chez l'enfant ?","a":"<div class=\"notion-course\"><p>Chez l'enfant, on retrouve plus spécifiquement le <strong>syndrome d'<span class=\"nc-red\">hyperactivité</span></strong>, le <strong>syndrome d'inattention</strong> et le <strong>syndrome autistique</strong>.</p></div>"},{"i":"1608253002fa","n":61,"o":"61-5","u":"Définition","t":"Connaître les grandes catégories diagnostiques chez l’enfant, l’adolescent et l’adulte","q":"Comment caractérise-t-on la catégorie des troubles du neurodéveloppement ?","a":"<div class=\"notion-course\"><p>Les <span class=\"nc-yellow_bg\">troubles du neurodéveloppement</span> sont caractérisés par un début survenant durant le <strong>développement psychomoteur</strong>. Ils incluent notamment le trouble du développement <span class=\"nc-red\">intellectuel</span>, les troubles des <span class=\"nc-red\">acquisitions</span> et des <span class=\"nc-red\">apprentissages</span>, le <strong>TDAH</strong>, les <strong>TSA</strong> et les <span class=\"nc-red\">tics</span>.</p></div>"},{"i":"216e1dc48805","n":61,"o":"61-5","u":"Définition","t":"Connaître les grandes catégories diagnostiques chez l’enfant, l’adolescent et l’adulte","q":"Quelles grandes familles orientent le raisonnement psychiatrique ?","a":"<div class=\"notion-course\"><ul><li>TND, psychoses, troubles dépressifs/bipolaires, anxiété, TOC, symptômes somatiques, traumatismes/stress et addictions.</li><li>Liste pédagogique non exhaustive : ajouter notamment conduites alimentaires, personnalité, troubles neurocognitifs et dissociatifs.</li></ul></div>"},{"i":"4648d3ae25c9","n":61,"o":"61-5","u":"Définition","t":"Connaître les grandes catégories diagnostiques chez l’enfant, l’adolescent et l’adulte","q":"Comment se manifestent les troubles anxieux ?","a":"<div class=\"notion-course\"><p>Les <span class=\"nc-yellow_bg\">troubles anxieux</span> se manifestent par une <strong>anxiété excessive et des perturbations comportementales</strong> apparentées, se distinguant par l'objet ou la situation déclenchante.</p></div>"},{"i":"cff31ae67199","n":61,"o":"61-5","u":"Définition","t":"Connaître les grandes catégories diagnostiques chez l’enfant, l’adolescent et l’adulte","q":"Quelle est la caractéristique principale des troubles de l'humeur ?","a":"<div class=\"notion-course\"><p>Les <span class=\"nc-yellow_bg\">troubles de l'humeur</span> se caractérisent par une <strong>perturbation des affects et de leur régulation</strong>, avec des modifications cognitives et physiologiques associées.</p></div>"},{"i":"49b03e6edc9f","n":61,"o":"61-1","u":"Définition","t":"Connaître les signes, symptômes et syndromes en psychiatrie","q":"Comment distinguer hallucination et illusion ?","a":"<div class=\"notion-course\"><ul><li>Hallucination : <span class=\"nc-yellow_bg\">perception sans objet</span> extérieur correspondant.</li><li>Illusion : déformation d’un stimulus réellement présent.</li></ul></div>"},{"i":"2196ec2b7fb9","n":61,"o":"61-1","u":"Définition","t":"Connaître les signes, symptômes et syndromes en psychiatrie","q":"Comment décrire une idée délirante ?","a":"<div class=\"notion-course\"><ul><li>Thème, mécanisme, organisation, adhésion, vécu affectif, retentissement et chronologie.</li><li>Évaluer <span class=\"nc-red\">attention</span>/conscience, substances, contexte culturel, risques et causes somatiques.</li></ul></div>"},{"i":"400da06e0fcb","n":61,"o":"61-1","u":"Définition","t":"Connaître les signes, symptômes et syndromes en psychiatrie","q":"Quelle différence entre anhédonie, aboulie et apragmatisme ?","a":"<div class=\"notion-course\"><ul><li><span class=\"nc-red nc-bold\">Anhédonie</span> : diminution du plaisir ; <span class=\"nc-blue_bg\">aboulie</span> : difficulté à vouloir/initier ; apragmatisme : difficulté à réaliser une action finalisée.</li></ul></div>"},{"i":"ca40786ef603","n":61,"o":"61-1","u":"Définition","t":"Connaître les signes, symptômes et syndromes en psychiatrie","q":"Quels phénomènes différencier devant une pensée intrusive ?","a":"<div class=\"notion-course\"><ul><li>Obsession : intrusive, répétitive, habituellement indésirable, insight variable.</li><li>Délire : conviction pathologique, peu accessible à la critique, à interpréter culturellement et cliniquement.</li></ul></div>"},{"i":"f49fe885f884","n":61,"o":"61-2","u":"Définition","t":"Connaître l’approche catégorielle en psychiatrie","q":"Comment compléter l’approche catégorielle ?","a":"<div class=\"notion-course\"><ul><li>Par une description dimensionnelle : intensité des symptômes, fonctionnement, évolution, besoins et comorbidités.</li></ul></div>"},{"i":"40b15f407100","n":61,"o":"61-4","u":"Définition","t":"Connaître les systèmes nosographiques existants","q":"Qui produit CIM, DSM et CIF, et que décrivent-ils ?","a":"<div class=\"notion-course\"><ul><li>CIM : OMS, maladies et codage diagnostique.</li><li>DSM : APA, troubles mentaux ; DSM-5-TR publié en 2022.</li><li>CIF : OMS, fonctionnement et handicap ; pas un diagnostic de maladie.</li></ul></div>"},{"i":"196f997ea3cf","n":61,"o":"61-5","u":"Définition","t":"Connaître les grandes catégories diagnostiques chez l’enfant, l’adolescent et l’adulte","q":"Un trouble à symptomatologie somatique impose-t-il l’absence de maladie organique ?","a":"<div class=\"notion-course\"><ul><li>Non : une affection somatique peut coexister.</li><li>Le diagnostic repose sur les symptômes et les préoccupations/comportements excessifs avec retentissement, selon les critères.</li></ul></div>"}],"courseEdition":{"source":"notion","notionUrl":"https://app.notion.com/p/2ad37f85d94181988919cb587e47b711?pvs=204","reviewedAt":"2026-10-13","note":"Cours, cartes et arbres relus. Couleurs des passages Notion correspondants ; références et compléments identifiés dans chaque objectif.","sddVerifiedAt":"2026-10-13","sdd":[{"number":116,"title":"Anxiété","url":"https://livret.uness.fr/lisa/2026/Anxi%C3%A9t%C3%A9_SDD-116"}]},"arbre":{"rootId":"entry","nodes":[{"id":"entry","kind":"decision","label":"Urgence, confusion ou mise en danger ?","detail":"<ul><li>Conscience/attention, début brutal, toxiques, signes somatiques et risque suicidaire.</li></ul>","branches":[{"label":"Oui / suspicion","to":"urgent"},{"label":"Non, entretien possible","to":"decrire"}]},{"id":"urgent","kind":"urgent","label":"Évaluation médicale urgente adaptée au tableau","detail":"<ul><li>Ne pas attribuer une confusion à un trouble psychiatrique sans bilan.</li><li>Sécuriser et orienter, puis poursuivre la démarche diagnostique.</li></ul>","branches":[]},{"id":"decrire","kind":"decision","label":"Explorer les huit domaines sémiologiques","detail":"<ul><li>Séparer signes observés, symptômes vécus et syndromes.</li><li>Caractériser pensée, perception, affects, comportement et insight.</li></ul>","branches":[{"label":"Phénomènes décrits","to":"temps"}]},{"id":"temps","kind":"decision","label":"Chronologie et retentissement compatibles ?","detail":"<ul><li>Durée, trajectoire développementale ou rupture, détresse et autonomie.</li><li>Un syndrome ne suffit pas à nommer un trouble.</li></ul>","branches":[{"label":"Données suffisantes","to":"differentiels"},{"label":"Données manquantes","to":"doute"}]},{"id":"doute","kind":"uncertain","label":"Compléter et réévaluer","detail":"<ul><li>Entourage avec accord/cadre adapté, observations longitudinales et suivi.</li></ul>","branches":[]},{"id":"differentiels","kind":"decision","label":"Une meilleure explication est-elle présente ?","detail":"<ul><li>Substance, médicament, affection somatique ou autre trouble mental.</li><li>Examens ciblés ; rechercher aussi les comorbidités.</li></ul>","branches":[{"label":"Cause alternative probable","to":"cause"},{"label":"Catégorie psychiatrique à préciser","to":"classer"}]},{"id":"cause","kind":"finish","label":"Traiter/explorer la cause et suivre le syndrome","detail":"<ul><li>Un trouble somatique et un trouble psychiatrique peuvent coexister.</li></ul>","branches":[]},{"id":"classer","kind":"finish","label":"Catégorie, critères, dimensions et comorbidités","detail":"<ul><li>Utiliser CIM/DSM en précisant le système ; évaluer intensité et fonctionnement.</li><li>Inclure particularités d’âge et besoins de soins.</li></ul>","branches":[]}]}};
